def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)]
    sell_book = []  # [(price, arrival_time, id, qty)]
    arrival_time_counter = [0]
    order_map = {}  # id -> (side, price, qty, arrival_time)

    def add_buy_order(id, price, qty, arrival_time):
        buy_book.append((price, arrival_time, id, qty))
        buy_book.sort(key=lambda x: (-x[0], x[1]))

    def add_sell_order(id, price, qty, arrival_time):
        sell_book.append((price, arrival_time, id, qty))
        sell_book.sort(key=lambda x: (x[0], x[1]))

    def match_buy_order(id, price, qty):
        nonlocal trades
        while qty > 0 and sell_book:
            sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
            if sell_price > price:
                break
            trade_qty = min(qty, sell_qty)
            trades.append([id, sell_id, sell_price, trade_qty])
            qty -= trade_qty
            if trade_qty == sell_qty:
                sell_book.pop(0)
                del order_map[sell_id]
            else:
                sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)

        if qty > 0:
            add_buy_order(id, price, qty, arrival_time_counter[0])
            order_map[id] = ('buy', price, qty, arrival_time_counter[0])

    def match_sell_order(id, price, qty):
        nonlocal trades
        while qty > 0 and buy_book:
            buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
            if buy_price < price:
                break
            trade_qty = min(qty, buy_qty)
            trades.append([buy_id, id, buy_price, trade_qty])
            qty -= trade_qty
            if trade_qty == buy_qty:
                buy_book.pop(0)
                del order_map[buy_id]
            else:
                buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

        if qty > 0:
            add_sell_order(id, price, qty, arrival_time_counter[0])
            order_map[id] = ('sell', price, qty, arrival_time_counter[0])

    for order in orders:
