                    if trade_qty == sell_qty:
                        sell_book.pop(0)
                        del order_map[sell_id]
                    else:
                        sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
            else:
                while qty > 0 and buy_book:
                    buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
                    if buy_price < price:
                        break
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, id, buy_price, trade_qty])
                    qty -= trade_qty
                    if trade_qty == buy_qty:
                        buy_book.pop(0)
                        del order_map[buy_id]
                    else:
                        buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

        elif order[0] == 'market':
            _, id, side, qty = order
            if side == 'buy':
                while qty > 0 and sell_book:
                    sell_price, sell_arrival, sell_id, sell_qty = sell_book[0]
                    trade_qty = min(qty, sell_qty)
                    trades.append([id, sell_id, sell_price, trade_qty])
                    qty -= trade_qty
                    if trade_qty == sell_qty:
                        sell_book.pop(0)
                        del order_map[sell_id]
                    else:
                        sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
            else:
                while qty > 0 and buy_book:
                    buy_price, buy_arrival, buy_id, buy_qty = buy_book[0]
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, id, buy_price, trade_qty])
                    qty -= trade_qty
                    if trade_qty == buy_qty:
                        buy_book.pop(0)
                        del order_map[buy_id]
                    else:
                        buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)

        elif order[0] == 'cancel':
            _, id = order
            if id in order_map:
                side, price, qty, arrival = order_map[id]
                if side == 'buy':
                    buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != id]
                else:
                    sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != id]
                del order_map[id]

    return trades

